-- Ejecuta este archivo en Neon SQL Editor. No crea una base de datos; usa la base seleccionada.
CREATE TABLE IF NOT EXISTS products (id BIGSERIAL PRIMARY KEY, name VARCHAR(150) NOT NULL, description TEXT NOT NULL, category VARCHAR(80) NOT NULL, price NUMERIC(12,2) NOT NULL DEFAULT 0, image VARCHAR(500), specifications JSONB, active SMALLINT NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_products_category ON products(category); CREATE INDEX IF NOT EXISTS idx_products_active ON products(active);
CREATE TABLE IF NOT EXISTS contacts (id BIGSERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL, phone VARCHAR(30), company VARCHAR(150), subject VARCHAR(150), message TEXT NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'new', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_contacts_email ON contacts(email); CREATE INDEX IF NOT EXISTS idx_contacts_status ON contacts(status);
CREATE TABLE IF NOT EXISTS calculator_requests (id BIGSERIAL PRIMARY KEY, users INTEGER NOT NULL, operation VARCHAR(50) NOT NULL, redundancy VARCHAR(50) NOT NULL, estimated_total NUMERIC(12,2) NOT NULL, result_json JSONB, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_calculator_created ON calculator_requests(created_at);
CREATE TABLE IF NOT EXISTS quotes (id BIGSERIAL PRIMARY KEY, quote_number VARCHAR(40) NOT NULL UNIQUE, customer_name VARCHAR(100) NOT NULL, customer_email VARCHAR(150) NOT NULL, customer_phone VARCHAR(30), company VARCHAR(150), notes TEXT, total NUMERIC(12,2) NOT NULL DEFAULT 0, status VARCHAR(30) NOT NULL DEFAULT 'pending', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_quotes_email ON quotes(customer_email); CREATE INDEX IF NOT EXISTS idx_quotes_status ON quotes(status);
CREATE TABLE IF NOT EXISTS quote_items (id BIGSERIAL PRIMARY KEY, quote_id BIGINT NOT NULL REFERENCES quotes(id) ON DELETE CASCADE, product_id BIGINT REFERENCES products(id) ON DELETE SET NULL, item_type VARCHAR(30) NOT NULL DEFAULT 'product', item_name VARCHAR(180) NOT NULL, quantity INTEGER NOT NULL DEFAULT 1, unit_price NUMERIC(12,2) NOT NULL DEFAULT 0, subtotal NUMERIC(12,2) NOT NULL DEFAULT 0, details_json JSONB, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_quote_items_quote ON quote_items(quote_id);
CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(128) NOT NULL, password_salt VARCHAR(64) NOT NULL, role VARCHAR(30) NOT NULL DEFAULT 'user', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS articles (id BIGSERIAL PRIMARY KEY, title VARCHAR(200) NOT NULL, category VARCHAR(80) NOT NULL, summary TEXT NOT NULL, content TEXT NOT NULL, published_at DATE NOT NULL, active SMALLINT NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_articles_date ON articles(published_at); CREATE INDEX IF NOT EXISTS idx_articles_active ON articles(active);
